// @ts-nocheck
// #region 5. HASHES & CACHE UTILS
export function materialHash(cfg) {
    return `${cfg.materialPreset}|${cfg.sketchBaseColor}|${cfg.sketchLineColor}|${cfg.sketchLineThickness}|${cfg.sketchSteps}|${cfg.overrideMaterial}|${cfg.metalness}|${cfg.roughness}|${cfg.clearcoat}|${cfg.clearcoatRoughness}|${cfg.transmission}|${cfg.thickness}|${cfg.ior}|${cfg.iridescence}|${cfg.iridescenceIOR}|${cfg.sheen}|${cfg.sheenRoughness}|${cfg.sheenColor}|${cfg.envMapIntensity}|${cfg.emissiveIntensity}|${cfg.emissiveColor}|${cfg.reflectivity}|${cfg.opacity}`
}

export function lightingHash(cfg) {
    let h = `${cfg.ambientLightIntensity}|${cfg.directionalLightIntensity}|${cfg.directionalLightColor}|${cfg.dirLightPosX}|${cfg.dirLightPosY}|${cfg.dirLightPosZ}|${cfg.enableShadows}|${cfg.shadowMapSize}|${cfg.shadowBias}|${cfg.shadowNormalBias}`
    if (cfg.extraLights?.length) {
        for (const el of cfg.extraLights) {
            if (!el) continue
            h += `|EL:${el.enabled}:${el.lightType}:${el.color}:${el.intensity}:${el.posX}:${el.posY}:${el.posZ}:${el.distance}:${el.decay}:${el.angle}:${el.penumbra}:${el.targetX}:${el.targetY}:${el.targetZ}:${el.castShadow}`
        }
    }
    return h
}

export function envHash(cfg) {
    return `${cfg.enableEnvironment}|${cfg.environmentType}|${cfg.environmentPreset}|${cfg.hdriPreset}|${cfg.customHdriUrl}`
}

export function effectsHash(cfg) {
    return `${cfg.bloomEnabled}|${cfg.bloomStrength}|${cfg.bloomThreshold}|${cfg.bloomRadius}|${cfg.toneMapping}|${cfg.exposure}|${cfg.enableFXAA}|${cfg.enableColorGrading}|${cfg.brightness}|${cfg.contrast}|${cfg.saturation}|${cfg.enableVignette}|${cfg.vignetteOffset}|${cfg.vignetteDarkness}|${cfg.enableChromaticAberration}|${cfg.chromaticAberrationStrength}|${cfg.enableFilmGrain}|${cfg.filmGrainIntensity}|${cfg.enableSSAO}|${cfg.ssaoRadius}|${cfg.ssaoMinDistance}|${cfg.ssaoMaxDistance}|${cfg.enableDOF}|${cfg.dofFocus}|${cfg.dofAperture}|${cfg.dofMaxBlur}`
}

export function appearReplayHash(cfg) {
    let h = [
        cfg.appearReplay,
        cfg.modelScale,
        cfg.modelOffsetX,
        cfg.modelOffsetY,
        cfg.modelOffsetZ,
        cfg.modelRotationX,
        cfg.modelRotationY,
        cfg.modelRotationZ,
        cfg.dissolveEnabled,
        cfg.dissolveDuration,
        cfg.blurReveal,
        cfg.blurRevealIntensity,
        cfg.blurRevealDuration,
        cfg.appearOffsetX,
        cfg.appearOffsetY,
        cfg.appearOffsetZ,
        cfg.appearScale,
        cfg.appearRotateX,
        cfg.appearRotateY,
        cfg.appearRotateZ,
        cfg.dissolveNoiseScale,
        cfg.dissolveAmplitude,
        cfg.dissolveEdgeWidth,
        cfg.dissolveEmissiveColor,
        cfg.dissolveEmissiveIntensity,
        cfg.cameraPositionX,
        cfg.cameraPositionY,
        cfg.cameraPositionZ,
        cfg.orthoZoom,
        cfg.fov,
        cfg.enableScrollAnimation,
        cfg.scrollSmoothing,
        cfg.scrollAnchorEnabled,
        cfg.scrollAnchorMatch,
        cfg.scrollAnchorStrengthX,
        cfg.scrollAnchorStrengthY,
        cfg.scrollAnchorSmoothing,
        cfg.scrollProgressTransformEnabled,
        cfg.scrollTransformAnchorMatch,
        cfg.scrollProgressPositionX,
        cfg.scrollProgressPositionY,
        cfg.scrollProgressPositionZ,
        cfg.scrollProgressScale,
        cfg.scrollAnchorRotationX,
        cfg.scrollAnchorRotationY,
        cfg.scrollAnchorRotationZ,
    ].join("|")
    if (cfg.subSceneItems?.length) {
        for (const item of cfg.subSceneItems) {
            if (!item) continue
            h += `|SS:${item.visible}:${item.scale}:${item.offX}:${item.offY}:${item.offZ}:${item.rotX}:${item.rotY}:${item.rotZ}`
        }
    }
    return h
}

export function sceneConfigHash(cfg) {
    return (
        materialHash(cfg) +
        "||" +
        lightingHash(cfg) +
        "||" +
        envHash(cfg) +
        "||" +
        effectsHash(cfg)
    )
}
// #endregion
